<?php declare(strict_types=1);
use Kulturhus\Native\Shared\Db;
use Kulturhus\Verein\MemberBankVault;
function ownCreditRefundLegacy(PDO $db,callable $check,array $f):void
{
    require_once __DIR__.'/transfer-native-legacy.php';ownTransferPreviousLoad($db,\Kulturhus\Native\TestSupport::config());$old=new \Kulturhus\Verein\OwnPreviousTransferOrders($db,$f['actor'],new MemberBankVault($db,$f['actor'],$f['path']));$key=static fn()=>bin2hex(random_bytes(16));
    $case=($f['make'])('organisation');$wrong=$key();Db::run($db,"INSERT INTO contacts(id,club_id,kind,name)VALUES(?,?,'organisation','Own wrong legacy supplier')",[$wrong,$f['club']]);Db::run($db,'INSERT INTO supplier_bank_details(club_id,contact_id,iban,bic,actor_id,created_at)VALUES(?,?,?,?,?,?)',[$f['club'],$wrong,'DE89370400440532013000','',$f['actor'],gmdate('c')]);Db::run($db,'INSERT INTO finance_supplier_contacts VALUES(?,?,?,?,?,?,?)',[$f['club'],$case['creditEntry'],$wrong,1,'Own wrong legacy supplier',$f['actor'],gmdate('c')]);
    $purpose='Own genuine old credit supplier path';$preview=$old->preview($case['creditEntry'],$f['account'],$f['today'],$purpose);$order=$old->prepare($case['creditEntry'],$f['account'],$f['today'],$purpose,$preview['hash'],$key());$original=$old->get($order);$tables=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$before=ownOriginalDatabaseHash($db,$tables);$blocked=false;
    try{$f['orders']->approve($order,1);}catch(DomainException $error){$blocked=$error->getCode()===409;}
    $check($blocked&&ownOriginalDatabaseHash($db,$tables)===$before&&$f['orders']->get($order)['sealed_snapshot']===$original['sealed_snapshot'],'genuine committed version1 producer credit cannot approve its arbitrary supplier as the original buyer and preserves every whole row');
    $f['orders']->cancel($order,1);$input=($f['inputFor'])($case['creditEntry']);$review=$f['native']->prepare($input);$first=$f['native']->accept($input,$key(),$review['hash'],true);
    $check($first['result']['source']['source_version']===3&&$first['result']['source']['credit_refund']['buyer_contact_id']===$case['contact']&&$first['result']['source']['recipient']['iban_masked']==='DE •••• 9890'&&$first['result']['source']['recipient']['name']===$case['name'],'after conscious old-order cancellation a genuine new credit source ignores the wrong supplier link and binds only the real original buyer bank');
    $second=$f['invoices']->get($case['second'])['entry_id'];$approval=new \Kulturhus\Verein\InvoiceApprovals($db,$f['actor']);$state=$approval->state($second);$approval->approve($second,$state['hash'],$state['decision_id'],$key(),true);Db::run($db,'INSERT INTO finance_supplier_contacts VALUES(?,?,?,?,?,?,?)',[$f['club'],$second,$wrong,1,'Own wrong legacy supplier',$f['actor'],gmdate('c')]);
    $preview=$old->preview($second,$f['account'],$f['today'],$purpose);$exported=$old->prepare($second,$f['account'],$f['today'],$purpose,$preview['hash'],$key());$old->approve($exported,1);$xml=$old->export($exported,2);$before=ownOriginalDatabaseHash($db,$tables);
    $check($f['native']->orderXml($exported)===$xml&&ownOriginalDatabaseHash($db,$tables)===$before,'genuine previously exported version1 credit XML remains byte exact and read-only in its original history');
    $blocked=false;try{$f['orders']->export($exported,3);}catch(DomainException $error){$blocked=$error->getCode()===409;}$check($blocked&&ownOriginalDatabaseHash($db,$tables)===$before,'genuine earlier exported credit cannot silently re-export its obsolete arbitrary supplier as a new buyer-bound bank instruction');
}
